--!strict
-- L: our own translation tables (user 2026-11-13: "직접 번역표", every Roblox language,
-- each player sees their own). Korean is the source text everywhere in the code.
--
-- Tables: Shared/I18n/<lang>.lua = { [Korean] = translation }, generated by
-- tools/i18n/build.py from tools/i18n/tr/*.tsv (see tools/i18n/README.md).
-- A key may hold {1} {2} …: the values of a string.format / ".." text, matched
-- as a pattern; Korean values inside are translated too.
--
-- Client: L.start() watches every text on screen and in the world (TextLabel /
-- TextButton .Text, TextBox .PlaceholderText, ProximityPrompt texts) and swaps
-- Korean for the player's language, so most scripts need no change at all.
-- L.t(text) translates one string by hand (SetCore notifications, read-backs).
-- Server: L.t(text, player) for text that does not go through a GUI.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalizationService = game:GetService("LocalizationService")

local L = {}

-- Roblox's player languages (besides Korean, the source)
L.Languages = { "en", "es", "pt", "fr", "de", "it", "ja", "zh-cn", "zh-tw", "ru", "th", "tr", "vi", "id", "pl", "ar" }
local supported: {[string]: boolean} = { ko = true }
for _, code in ipairs(L.Languages) do supported[code] = true end

local folder = script.Parent:WaitForChild("I18n")

local COIN = "💰"
local GAP = "\u{2003}" -- CoinIcons swaps 💰 for this gap and lays a picture in it

local function hasHangul(s: string): boolean
	-- syllables U+AC00..U+D7A3 = EA B0 80 .. ED 9E A3
	return string.find(s, "[\234-\237][\128-\191][\128-\191]") ~= nil
end
L.hasHangul = hasHangul

-- "en-us" → "en", "zh-cn" / "zh-tw" / "zh-hk" kept apart, unknown → "en"
function L.codeFor(locale: string?): string
	local id = string.lower(locale or "")
	if id == "" then return "ko" end
	if string.sub(id, 1, 2) == "zh" then
		if string.find(id, "tw") or string.find(id, "hk") or string.find(id, "hant") or string.find(id, "mo") then
			return "zh-tw"
		end
		return "zh-cn"
	end
	local short = string.match(id, "^(%a+)") or id
	if supported[short] then return short end
	return "en"
end

-- the language a player sees (Studio: LocalPlayer / ReplicatedStorage attribute Lang overrides)
function L.langOf(player: Player?): string
	local p = player or Players.LocalPlayer
	if RunService:IsStudio() then
		local fg = game:GetService("ReplicatedStorage"):FindFirstChild("FashionGame")
		local o = (p and p:GetAttribute("Lang")) or (fg and fg:GetAttribute("Lang"))
		if type(o) == "string" and o ~= "" then return L.codeFor(o) end
	end
	local id = if p then p.LocaleId else ""
	if (id == nil or id == "") and RunService:IsClient() then id = LocalizationService.RobloxLocaleId end
	return L.codeFor(id)
end

type Book = {
	exact: {[string]: string},
	tmpls: { { pat: string, out: string, anchor: string, n: number } },
	cache: {[string]: string},
	cacheSize: number,
}
local books: {[string]: Book} = {}

local function norm(s: string): string
	-- CoinIcons' gap back to the coin mark, so texts match before and after it ran
	s = string.gsub(s, GAP, COIN)
	return s
end

local function escapePattern(s: string): string
	return (string.gsub(s, "[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0"))
end

local function bookFor(lang: string): Book?
	if lang == "ko" then return nil end
	local b = books[lang]
	if b then return b end
	local mod = folder:FindFirstChild(lang)
	if not mod and lang ~= "en" then return bookFor("en") end
	if not mod then return nil end
	local ok, data = pcall(require, mod)
	if not ok or type(data) ~= "table" then return nil end
	local fresh: Book = { exact = {}, tmpls = {}, cache = {}, cacheSize = 0 }
	for ko, tr in pairs(data :: any) do
		if type(ko) == "string" and type(tr) == "string" then
			local key = norm(ko)
			if string.find(key, "{%d+}") then
				-- pattern: literal pieces escaped, {n} → a capture; the out text keeps {n}
				local order = {}
				local pat = "^" .. string.gsub(escapePattern(key), "{(%d+)}", function(d)
					table.insert(order, tonumber(d))
					return "(.-)"
				end) .. "$"
				-- the longest literal piece: a quick plain find before trying the pattern
				local anchor = ""
				for piece in string.gmatch(string.gsub(key, "{%d+}", "\0"), "[^%z]+") do
					if #piece > #anchor then anchor = piece end
				end
				if #anchor > 0 then
					-- remap {n} in the translation to capture positions
					local pos = {}
					for i, d in ipairs(order) do pos[d] = i end
					local out = string.gsub(tr, "{(%d+)}", function(d)
						local i = pos[tonumber(d)]
						return if i then "{" .. i .. "}" else "{" .. d .. "}"
					end)
					table.insert(fresh.tmpls, { pat = pat, out = norm(out), anchor = anchor, n = #order })
				end
			else
				fresh.exact[key] = norm(tr)
				-- pieces glued to a name ("님 선곡", " (먹다 남김)") are also found without their edge spaces
				local bare = string.match(key, "^%s*(.-)%s*$")
				if bare ~= key and fresh.exact[bare] == nil then
					fresh.exact[bare] = norm(string.match(tr, "^%s*(.-)%s*$") or tr)
				end
			end
		end
	end
	-- the most specific patterns first
	table.sort(fresh.tmpls, function(a, b)
		if #a.anchor ~= #b.anchor then return #a.anchor > #b.anchor end
		return a.n < b.n
	end)
	books[lang] = fresh
	return fresh
end

local translate: (Book, string, number) -> string

local function tryTemplates(b: Book, s: string, depth: number): string?
	for _, t in ipairs(b.tmpls) do
		if string.find(s, t.anchor, 1, true) then
			local caps = { string.match(s, t.pat) }
			if #caps > 0 then
				return (string.gsub(t.out, "{(%d+)}", function(d)
					local v = caps[tonumber(d) :: number]
					if v == nil then return "" end
					if depth < 3 and hasHangul(v) then v = translate(b, v, depth + 1) end
					return v
				end))
			end
		end
	end
	return nil
end

local function splitJoin(b: Book, s: string, sep: string, depth: number): string?
	if not string.find(s, sep, 1, true) then return nil end
	local parts = string.split(s, sep)
	local changed = false
	for i, p in ipairs(parts) do
		if hasHangul(p) then
			local t = translate(b, p, depth + 1)
			if t ~= p then parts[i] = t; changed = true end
		end
	end
	return if changed then table.concat(parts, sep) else nil
end

translate = function(b: Book, s: string, depth: number): string
	if depth > 6 or not hasHangul(s) then return s end
	local hit = b.exact[s] or tryTemplates(b, s, depth)
	if hit then return hit end
	-- rich text: translate the text between tags
	if string.find(s, "<[%a/][^>]*>") then
		local changed = false
		local out = string.gsub(s, "()([^<>]+)()", function(_, piece)
			if hasHangul(piece) then
				local t = translate(b, piece, depth + 1)
				if t ~= piece then changed = true; return t end
			end
			return piece
		end)
		if changed then return out end
	end
	-- one line at a time, then " · " parts
	local r = splitJoin(b, s, "\n", depth) or splitJoin(b, s, " · ", depth)
	if r then return r end
	-- leading / trailing marks, emoji, numbers and spaces kept as they are
	local first, last
	if utf8.len(s) == nil then return s end
	for pos, cp in utf8.codes(s) do
		if cp >= 0xAC00 and cp <= 0xD7A3 then
			first = first or pos
			last = pos + 2 -- a syllable is 3 bytes
		end
	end
	if first and (first > 1 or last < #s) then
		local core = string.sub(s, first, last)
		local t = b.exact[core] or tryTemplates(b, core, depth)
		if t then return string.sub(s, 1, first - 1) .. t .. string.sub(s, last + 1) end
	end
	return s
end

-- Translate one text for the local player (client) or for `player` (server).
function L.t(text: string, player: Player?): string
	if type(text) ~= "string" or text == "" or not hasHangul(text) then return text end
	local b = bookFor(L.langOf(player))
	if not b then return text end
	local key = norm(text)
	local c = b.cache[key]
	if c then return c end
	local out = translate(b, key, 0)
	if b.cacheSize > 4000 then b.cache = {}; b.cacheSize = 0 end
	b.cache[key] = out
	b.cacheSize += 1
	return out
end

-- `shown` is the text on a label; is it `ko` (in any language)?
function L.is(shown: string, ko: string): boolean
	return shown == ko or shown == L.t(ko)
end

-------------------------------------------------------------------------------
-- Client: watch every text
local started = false
function L.start()
	if started or not RunService:IsClient() then return end
	started = true
	local lang = L.langOf()
	if lang == "ko" then return end
	local b = bookFor(lang)
	if not b then return end

	local watched = setmetatable({}, { __mode = "k" }) :: any

	local function fix(obj: Instance, prop: string)
		local cur = (obj :: any)[prop]
		if type(cur) == "string" and cur ~= "" and hasHangul(cur) then
			local tr = L.t(cur)
			if tr ~= cur then (obj :: any)[prop] = tr end
		end
	end

	local function watch(obj: Instance)
		if watched[obj] then return end
		local props
		if obj:IsA("TextLabel") or obj:IsA("TextButton") then
			props = { "Text" }
		elseif obj:IsA("TextBox") then
			props = { "PlaceholderText" } -- never what the player typed
		elseif obj:IsA("ProximityPrompt") then
			props = { "ActionText", "ObjectText" }
		else
			return
		end
		watched[obj] = true
		for _, prop in ipairs(props) do
			fix(obj, prop)
			obj:GetPropertyChangedSignal(prop):Connect(function() fix(obj, prop) end)
		end
	end

	local player = Players.LocalPlayer
	local playerGui = player:WaitForChild("PlayerGui")
	for _, d in ipairs(playerGui:GetDescendants()) do watch(d) end
	playerGui.DescendantAdded:Connect(watch)
	workspace.DescendantAdded:Connect(watch)
	task.spawn(function()
		local all = workspace:GetDescendants()
		for i, d in ipairs(all) do
			watch(d)
			if i % 4000 == 0 then task.wait() end
		end
	end)
end

return L
